    t.parts[0]=choice('finding','Which discrepancy needs correction?',[['mark','K mark beside the wrong pad','Compare the mark with D1.1/K.'],['absent','K mark absent','Inspect the silkscreen for the required mark.'],['route','A required copper route is absent','Trace the reference connections in copper.']],fault==='polarity'?'mark':fault==='missing-mark'?'absent':'route','Resolve the actual discrepancy and regenerate/reinspect affected outputs.','mapping')
