    t.artifact={kind:'files',variant:v,rows:[['Artifact','Inspected revision'],['Approved source',rev],['Copper Gerbers',stale==='copper'?'prior':rev],['Drill data',stale==='drill'?'prior':rev],['BOM',stale==='bom'?'prior':rev]]};t.context=`Identify the stale artifact against approved revision ${rev}. These are exercise files; renaming does not update their geometry or part inventory.`
