export const finalTaskIds=['9.1','9.2','5.2','6.2','8.5','9.4']
export function activityTasks(id:string):string[] {return id==='final'?finalTaskIds:id==='unit-basics'?['E.3','E.6','E.9']:id.startsWith('unit-')?unitTaskIds[Number(id.slice(5))]:id.startsWith('review:')?[reviewTaskFor(id.slice(7))]:[id]}
export function reviewTaskFor(skill:string):string {return ({components:'E.5',transistors:'E.6',workflow:'0.1',safety:'0.2',loop:'1.1',units:'1.3',calculation:'1.5',datasheet:'2.2',mapping:'4.4',breadboard:'3.1',measurement:'3.3',schematic:'4.3',footprint:'5.2',rules:'5.7',layout:'5.5',outputs:'6.2',assembly:'7.4',diagnosis:'8.5',evidence:'9.4'} as Record<string,string>)[skill]??'1.5'}
